#!/usr/bin/env pybricks-micropython
"""GreyForge: EV3 microSD / Pybricks 2.0. Experimental; ADR 019."""
# Pybricks 2.0 on the EV3 has math but no umath (tested on the brick: ImportError).
import math
import urandom as random
import _thread
from pybricks.tools import wait, StopWatch
from pybricks.hubs import EV3Brick
from pybricks.ev3devices import Motor, ColorSensor, UltrasonicSensor, GyroSensor, TouchSensor, InfraredSensor
from pybricks.parameters import Port, Direction, Button, Color
from pybricks.robotics import DriveBase

rb_hub = EV3Brick()
rb_failure = None
_rb_devices = {}
_rb_drive = None
_rb_busy = set()
_rb_jobs = []
_rb_clock = StopWatch()
_rb_gyro_modes = {}
_rb_cancelled = False


def rb_reset():
    global rb_failure
    rb_failure = None


def rb_check():
    if rb_failure is not None:
        raise RuntimeError("%s: %s" % rb_failure)


def rb_fail(block, message):
    global rb_failure
    if rb_failure is None:
        rb_failure = (block, message)
        print("RB_ERROR %s %s" % rb_failure)
    rb_check()


def rb_yield():
    yield 1
    rb_check()


def rb_wait(seconds, block=None):
    yield max(1, math.ceil(seconds * 1000)) if block is None else rb_duration(seconds, block)
    rb_check()


def rb_run(*processes):
    # Only the main thread advances IR generators, in declaration order.
    # Sleeping stacks keep their own deadline; finished stacks are removed.
    global _rb_cancelled
    rb_reset()
    _rb_cancelled = False
    tasks = [[process(), 0] for process in processes]
    try:
        while tasks:
            remaining = []
            for task in tasks:
                rb_check()
                if _rb_clock.time() >= task[1]:
                    try:
                        delay = next(task[0])
                        task[1] = _rb_clock.time() + delay
                    except StopIteration:
                        continue
                remaining.append(task)
            tasks = remaining
            if tasks:
                wait(1)
    except SystemExit:
        pass  # Detener todas las pilas sin registrar un error.
    finally:
        # Stop devices on failure/interruption, preserving normal end-of-stack
        # behavior (a run/drive block continues until explicitly stopped).
        if tasks:
            _rb_cancelled = True
            rb_stop_hardware()
            for task in tasks:
                task[0].close()
        # A worker may still be inside an official blocking API. Do not return
        # from the script while it owns hardware; stop above cancels movements.
        while any(not rb_job_done(job) for job in _rb_jobs):
            # Cover a worker that entered its hardware call just as cancellation
            # happened; Linux threads have no safe forced-termination primitive.
            if _rb_cancelled:
                rb_stop_hardware()
            wait(1)
        _rb_jobs.clear()


def rb_stop_hardware():
    try:
        if _rb_drive is not None:
            _rb_drive.stop()
    except OSError:
        pass  # Preserve the original failure if a device was unplugged.
    for kind, direction, device in _rb_devices.values():
        if kind == Motor:
            try:
                device.stop()
            except OSError:
                pass


def rb_job_done(job):
    if not job[0].acquire(False):
        return False
    job[0].release()
    return True


def rb_device(port, kind, block, direction="clockwise"):
    if port in _rb_busy:
        rb_fail(block, "El puerto tiene una maniobra pendiente en otro proceso")
    if port in _rb_devices:
        old_kind, old_direction, device = _rb_devices[port]
        if kind != old_kind or (kind == Motor and direction != old_direction):
            rb_fail(block, "Puerto ocupado por otro dispositivo o sentido de motor")
        return device
    try:
        if kind == Motor:
            sense = Direction.COUNTERCLOCKWISE if direction == "counterclockwise" else Direction.CLOCKWISE
            device = kind(port, sense)
        else:
            device = kind(port)
    except OSError:
        rb_fail(block, "Comprueba el motor o sensor conectado al puerto")
    _rb_devices[port] = (kind, direction, device)
    return device


def rb_motor(port, block):
    direction = _rb_devices[port][1] if port in _rb_devices else "clockwise"
    return rb_device(port, Motor, block, direction)


def rb_motor_stop(motor, mode):
    if mode == "hold":
        motor.hold()
    elif mode == "brake":
        motor.brake()
    else:
        motor.stop()


def rb_blocking(keys, block, operation, *args):
    # Worker threads execute one official hardware call, never generated IR.
    # The completion lock publishes exceptions back to the scheduler.
    if any(key in _rb_busy for key in keys):
        rb_fail(block, "Recurso ocupado por una maniobra de otro proceso")
    try:
        done = _thread.allocate_lock()
        done.acquire()
    except Exception:
        rb_fail(block, "No se pudo reservar la operación EV3")
    _rb_busy.update(keys)
    job = [done, None]
    _rb_jobs.append(job)

    def work():
        try:
            if not _rb_cancelled:
                operation(*args)
        except Exception as error:
            job[1] = str(error)
        finally:
            done.release()

    try:
        _thread.start_new_thread(work, ())
    except Exception:
        done.release()
        _rb_jobs.remove(job)
        _rb_busy.difference_update(keys)
        rb_fail(block, "No se pudo iniciar la operación EV3")
    try:
        while not done.acquire(False):
            yield 1
            rb_check()
        done.release()
        if job[1] is not None:
            rb_fail(block, "Operación EV3: " + job[1])
    finally:
        # Keep an unfinished worker for rb_run cleanup if this generator closes.
        if done.acquire(False):
            done.release()
            _rb_jobs.remove(job)
        _rb_busy.difference_update(keys)


def rb_drive_config(left, right, diameter, track, left_direction, right_direction, block):
    global _rb_drive, _rb_drive_ports
    if left == right:
        rb_fail(block, "La base necesita dos puertos de motor diferentes")
    if _rb_drive is not None:
        rb_drive(block).stop()
    _rb_drive = DriveBase(
        rb_device(left, Motor, block, left_direction),
        rb_device(right, Motor, block, right_direction),
        diameter, track,
    )
    _rb_drive_ports = (left, right)


def rb_drive(block):
    if _rb_drive is None:
        rb_fail(block, "Configura la base motriz antes de usarla")
    if any(port in _rb_busy for port in _rb_drive_ports):
        rb_fail(block, "La base tiene una maniobra pendiente en otro proceso")
    return _rb_drive


def rb_drive_move(mode, value, block):
    drive = rb_drive(block)
    operation = drive.straight if mode == "straight" else drive.turn
    yield from rb_blocking(_rb_drive_ports, block, operation, value)


def rb_gyro(port, mode, block):
    # v2.0: switching between angle() and speed() resets the measured angle.
    if port in _rb_gyro_modes and _rb_gyro_modes[port] != mode:
        rb_fail(block, "No combines ángulo y velocidad del mismo giroscopio EV3")
    _rb_gyro_modes[port] = mode
    return rb_device(port, GyroSensor, block)


def rb_light(color):
    rb_hub.light.on({"GREEN": Color.GREEN, "RED": Color.RED, "ORANGE": Color.ORANGE}[color])


def rb_beep(frequency, milliseconds, block):
    if "speaker" in _rb_busy:
        rb_fail(block, "El altavoz tiene un sonido pendiente en otro proceso")
    _rb_busy.add("speaker")
    try:
        # v2.0 documents negative duration as a non-blocking continuous tone.
        rb_hub.speaker.beep(frequency, -1)
        yield from rb_wait(milliseconds / 1000)
    finally:
        rb_hub.speaker.beep(frequency, 0)
        _rb_busy.remove("speaker")



# Serie, tiempo y mensajes. La consola MicroPython conserva los baudios del firmware.
import sys
import uselect as select
import utime as time

def _rb_now():
    return time.ticks_ms() if hasattr(time, "ticks_ms") else int(time.monotonic() * 1000)

def _rb_elapsed(start):
    if hasattr(time, "ticks_diff"):
        return time.ticks_diff(_rb_now(), start)
    return _rb_now() - start

_rb_start_time = _rb_now()
_rb_timer_time = _rb_start_time
_rb_messages = {}
_rb_serial_buffer = ""
_rb_poll = None

def rb_millis():
    return _rb_elapsed(_rb_start_time)

def rb_timer():
    return _rb_elapsed(_rb_timer_time)

def rb_timer_reset():
    global _rb_timer_time
    _rb_timer_time = _rb_now()

def rb_console_baud(baud, block):
    if baud != 115200:
        rb_fail(block, "La consola MicroPython requiere 115200 baudios; no configura UART adicionales")

def rb_serial_available(block):
    global _rb_poll
    try:
        if _rb_poll is None:
            _rb_poll = select.poll()
            _rb_poll.register(sys.stdin, select.POLLIN)
        return any(flags & select.POLLIN for stream, flags in _rb_poll.poll(0))
    except (OSError, ValueError, AttributeError):
        rb_fail(block, "La consola no admite lectura sin bloqueo")

def rb_serial_line(block):
    global _rb_serial_buffer
    for _ in range(64):
        if not rb_serial_available(block):
            break
        char = sys.stdin.read(1)
        if not char:
            break
        if char == "\n":
            result = _rb_serial_buffer
            _rb_serial_buffer = ""
            return result
        if char != "\r":
            _rb_serial_buffer += char
        if len(_rb_serial_buffer.encode("utf-8")) > 256:
            rb_fail(block, "Línea serie demasiado larga (máximo 256 bytes)")
    return ""

def rb_send(message):
    _rb_messages[message] = (_rb_messages.get(message, 0) + 1) & 0xFFFFFFFF

def rb_message_version(message):
    return _rb_messages.get(message, 0)
def rb_finite(value, block):
    if (value != value) or abs(value) > 3.4028234663852886e38:
        rb_fail(block, "Número fuera de rango finito")
    return value


def rb_integer(value, block):
    rb_finite(value, block)
    if value != math.floor(value) or value < -2147483648 or value > 2147483647:
        rb_fail(block, "Se requiere un entero de 32 bits")
    return int(value)


def rb_number(value, minimum, maximum, integer, block):
    rb_finite(value, block)
    if value < minimum or value > maximum:
        rb_fail(block, "Entrada numérica fuera de límites")
    return rb_integer(value, block) if integer else value


def rb_duration(seconds, block):
    rb_finite(seconds, block)
    if seconds < 0 or seconds * 1000 > 2147483647:
        rb_fail(block, "Duración fuera de límites")
    return max(1, math.ceil(seconds * 1000))


def rb_add(a, b, block):
    return rb_finite(a + b, block)


def rb_subtract(a, b, block):
    return rb_finite(a - b, block)


def rb_multiply(a, b, block):
    return rb_finite(a * b, block)


def rb_divide(a, b, block):
    if b == 0:
        rb_fail(block, "División entre cero")
    return rb_finite(a / b, block)


def rb_modulo(a, b, block):
    if b == 0:
        rb_fail(block, "Módulo entre cero")
    return rb_finite(a - b * math.floor(a / b), block)


def rb_random(a, b, block):
    a, b = rb_integer(a, block), rb_integer(b, block)
    if a > b:
        rb_fail(block, "Intervalo de azar invertido")
    # getrandbits existe en MicroPython; rechazo evita sesgo y soporta los 32 bits.
    width = b - a + 1
    bits, remainder = 0, width - 1
    while remainder:
        bits += 1
        remainder >>= 1
    if bits == 0:
        return a
    while True:
        offset = random.getrandbits(bits)
        if offset < width:
            return a + offset


def rb_less(a, b, block):
    return a < b


def rb_less_equal(a, b, block):
    return a <= b


def rb_greater(a, b, block):
    return a > b


def rb_greater_equal(a, b, block):
    return a >= b


def rb_join(a, b, block):
    return a + b


def rb_letter(index, text, block):
    index = rb_integer(index, block)
    return text[index - 1] if 1 <= index <= len(text) else ""


def rb_length(text, block):
    return len(text)


def rb_contains(text, search, block):
    return search in text


def rb_substring(text, start, end, start_mode, end_mode, block):
    start, end = rb_integer(start, block), rb_integer(end, block)
    if start_mode == "end":
        start = len(text) - start + 1
    if end_mode == "end":
        end = len(text) - end + 1
    start, end = max(1, start), min(len(text), end)
    return text[start - 1:end] if start <= end else ""


def rb_find(search, text, mode, block):
    # Recorremos puntos de código; no dependemos de rfind en el firmware.
    found = 0
    for index in range(len(text) - len(search) + 1):
        if text[index:index + len(search)] == search:
            found = index + 1
            if mode == "first":
                break
    return found


def rb_round(value, block):
    return rb_finite(math.floor(value + 0.5), block)


def rb_math(function, value, block):
    angle = value * math.pi / 180
    if (function == "sqrt" and value < 0) or (function in ("ln", "log10") and value <= 0):
        rb_fail(block, "Dominio matemático inválido")
    if function in ("asin", "acos") and abs(value) > 1:
        rb_fail(block, "Dominio trigonométrico inválido")
    if function == "tan" and abs(math.cos(angle)) < 1e-7:
        rb_fail(block, "Tangente indefinida")
    operations = {
        "abs": lambda: abs(value), "floor": lambda: math.floor(value), "ceil": lambda: math.ceil(value),
        "sqrt": lambda: math.sqrt(value), "sin": lambda: math.sin(angle), "cos": lambda: math.cos(angle),
        "tan": lambda: math.tan(angle), "asin": lambda: math.asin(value) * 180 / math.pi,
        "acos": lambda: math.acos(value) * 180 / math.pi, "atan": lambda: math.atan(value) * 180 / math.pi,
        "ln": lambda: math.log(value), "log10": lambda: math.log10(value),
        "exp": lambda: math.exp(value), "pow10": lambda: 10 ** value,
    }
    if function not in operations:
        rb_fail(block, "Función matemática desconocida")
    try:
        return rb_finite(operations[function](), block)
    except (ValueError, OverflowError):
        rb_fail(block, "Resultado matemático fuera de rango")


def rb_to_number(text, mode, block):
    text = text.strip(" \t\n\r\v\f")
    # Validate decimal syntax without depending on a regex module in the hub.
    part = text.lower().split("e")
    if len(part) > 2:
        rb_fail(block, "Texto numérico inválido")
    for index, value in enumerate(part):
        value = value[1:] if value[:1] in ("+", "-") else value
        pieces = value.split(".") if index == 0 else [value]
        digits = "".join(pieces)
        if len(pieces) > 2 or not digits or any(c < "0" or c > "9" for c in digits):
            rb_fail(block, "Texto numérico inválido")
    value = rb_finite(float(text), block)
    return rb_integer(int(value), block) if mode == "integer" else value


def rb_to_text(value, block):
    if isinstance(value, str):
        return value
    if isinstance(value, bool):
        return "true" if value else "false"
    rb_finite(value, block)
    return "0" if value == 0 else "%.6g" % value


def rb_char_code(text, block):
    if not text:
        rb_fail(block, "Texto vacío sin código de carácter")
    return ord(text[0])


def rb_code_char(code, block):
    code = rb_integer(code, block)
    if code < 0 or code > 0x10FFFF or 0xD800 <= code <= 0xDFFF:
        rb_fail(block, "Código Unicode inválido")
    return chr(code)


def rb_map(value, a, b, c, d, block):
    return rb_add(rb_multiply(rb_divide(value - a, b - a, block), d - c, block), c, block)


def rb_clamp(value, minimum, maximum, block):
    if minimum > maximum:
        rb_fail(block, "Límites invertidos")
    return max(minimum, min(maximum, value))




def proceso_1():
    if False:
        yield 1
    yield from rb_blocking((Port.A,), "ev3-13", rb_motor(Port.A, "ev3-13").run_angle, 500, 90)
    rb_motor_stop(rb_motor(Port.A, "ev3-14"), "hold")
    print(rb_finite(rb_motor(Port.A, "ev3-15").angle(), "ev3-15"))

def main():
    rb_run(proceso_1)

main()
